SINA_SMART["physio1-hypothalamus-pituitary"] = {"lecture":"physio1-hypothalamus-pituitary","title":"Hypothalamus and pituitary","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-hypothalamus-pituitary:e1","text":"Anterior pituitary: controlled by hypothalamic hormones via portal vessels.","topic":"The hypothalamus","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-hypothalamus-pituitary:e0","text":"Posterior pituitary: ADH and oxytocin made in SON and PVN, released from axon terminals.","topic":"Posterior pituitary: ADH and oxytocin","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-hypothalamus-pituitary:e2","text":"ADH ↑ with osmolality, ↓ volume, angiotensin II; ↓ with alcohol.","topic":"Posterior pituitary: ADH and oxytocin","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-hypothalamus-pituitary:e3","text":"V2 (Gs) → aquaporin-2; V1A (Gq) → vasoconstriction.","topic":"Posterior pituitary: ADH and oxytocin","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-hypothalamus-pituitary:e4","text":"Central DI: no ADH. Nephrogenic DI: resistance (V2 mutation, lithium).","topic":"Posterior pituitary: ADH and oxytocin","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-hypothalamus-pituitary:e5","text":"SIADH: concentrated urine, dilutional hyponatraemia.","topic":"Posterior pituitary: ADH and oxytocin","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-hypothalamus-pituitary:e6","text":"Oxytocin: labour contractions, milk ejection.","topic":"Posterior pituitary: ADH and oxytocin","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-hypothalamus-pituitary:e7","text":"TSH, LH, FSH share an α subunit; ACTH comes from POMC.","topic":"Anterior pituitary and its controllers","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-hypothalamus-pituitary:e8","text":"GH: JAK2/STAT; diabetogenic; acts directly and via IGF-1.","topic":"Growth hormone","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-hypothalamus-pituitary:e9","text":"Prolactin: tonic dopamine (D2) inhibition; TRH stimulates; inhibits GnRH.","topic":"Prolactin","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1wfc72l":"a","1qyvkai":"a","4b0fmh":"a","o5dcaq":"a","llqxkt":"a","13z7i6o":"a","1vo76hb":"a","1mlvl1b":"a","3irjm0":"a","q78u8z":"a","1td87mn":"a","1wc1afx":"a","ue10t0":"a","12hx9qu":"a","9dgdxz":"a","y68w3c":"a","1yx78yr":"a","5sn7xe":"x"},"mapCounts":{"verified":0,"auto":17,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-hypothalamus-pituitary:e1":{"s":0,"u":["Anterior pituitary: controlled by hypothalamic hormones via portal vessels.","In the endocrine system it controls the pituitary two ways: neural (magnocellular neurons whose axons end in the posterior pituitary ) and vascular (parvocellular neurons releasing hypophysiotropic hormones at the median eminence into the portal vessels to the anterior pituitary )."],"dp":[]},"physio1-hypothalamus-pituitary:e0":{"s":1,"u":["Posterior pituitary: ADH and oxytocin made in SON and PVN, released from axon terminals.","Both are made in magnocellular neurons of the supraoptic and paraventricular nuclei as precursors (ADH with neurophysin II; oxytocin with neurophysin I), transported down axons and released by exocytosis."],"dp":[]},"physio1-hypothalamus-pituitary:e2":{"s":1,"u":["ADH ↑ with osmolality, ↓ volume, angiotensin II; ↓ with alcohol.","ADH (arginine vasopressin) rises with plasma osmolality (osmoreceptors shrink when dehydrated) and with falls in blood volume/pressure (baroreceptors via CN IX and X to the NTS; also angiotensin II ).","Pain, nausea and stress increase it; alcohol decreases it."],"dp":[]},"physio1-hypothalamus-pituitary:e3":{"s":1,"u":["V2 (Gs) → aquaporin-2; V1A (Gq) → vasoconstriction.","Receptors are GPCRs: V2 (Gs) on collecting duct principal cells inserts aquaporin-2 → water reabsorption, concentrated urine; V1A (Gq) → vasoconstriction and hepatic glycogenolysis; V1B (V3) → ACTH release."],"dp":[]},"physio1-hypothalamus-pituitary:e4":{"s":1,"u":["Central DI: no ADH. Nephrogenic DI: resistance (V2 mutation, lithium).","Diabetes insipidus : central (low ADH: trauma, surgery, tumours, inflammation) or nephrogenic (renal resistance: X-linked V2 receptor mutations, lithium, hypokalaemia): large volumes of dilute urine."],"dp":[]},"physio1-hypothalamus-pituitary:e5":{"s":1,"u":["SIADH: concentrated urine, dilutional hyponatraemia.","SIADH : excess ADH (tumours, brain injury): small volumes of concentrated urine and dilutional hyponatraemia .","Receptors are GPCRs: V2 (Gs) on collecting duct principal cells inserts aquaporin-2 → water reabsorption, concentrated urine; V1A (Gq) → vasoconstriction and hepatic glycogenolysis; V1B (V3) → ACTH release."],"dp":[]},"physio1-hypothalamus-pituitary:e6":{"s":1,"u":["Oxytocin: labour contractions, milk ejection.","Oxytocin is released in response to stretch of the reproductive tract and nipple stimulation (synchronous high-frequency firing); it causes uterine contraction in labour and milk ejection (myoepithelial cells)."],"dp":[]},"physio1-hypothalamus-pituitary:e7":{"s":2,"u":["TSH, LH, FSH share an α subunit; ACTH comes from POMC.","Six hormones in three families: glycoproteins TSH, FSH, LH (shared α subunit; β gives specificity); POMC-derived ACTH (plus β-endorphin, MSH); and the GH/prolactin family.","Hypothalamic controllers: CRH → ACTH, TRH → TSH (and prolactin), GHRH → GH, somatostatin ⊣ GH, GnRH → LH and FSH, dopamine ⊣ prolactin."],"dp":[]},"physio1-hypothalamus-pituitary:e8":{"s":3,"u":["GH: JAK2/STAT; diabetogenic; acts directly and via IGF-1.","Its receptor is a cytokine receptor : GH binding causes dimerisation and activates JAK2-STAT ."],"dp":[]},"physio1-hypothalamus-pituitary:e9":{"s":4,"u":["Prolactin: tonic dopamine (D2) inhibition; TRH stimulates; inhibits GnRH.","It is under tonic dopamine inhibition (D2, Gi) from the arcuate and PVN; somatostatin and GABA also inhibit.","TRH stimulates prolactin, which is why primary hypothyroidism can raise prolactin and cause galactorrhoea and menstrual disturbance."],"dp":[{"h":"Why a pituitary stalk injury raises prolactin but lowers everything else","t":"Every anterior pituitary hormone except prolactin needs a hypothalamic releasing hormone to keep going. Prolactin is the opposite: its dominant control is inhibition by dopamine. If the stalk is compressed by a tumour or cut by trauma, dopamine can no longer reach the lactotrophs, so prolactin rises (stalk effect) while ACTH, TSH, LH, FSH and GH fall. A mildly raised prolactin with a large non-secreting pituitary mass is therefore not proof of a prolactinoma."}]}},"meta":{"1wfc72l":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e0/recall/1"},"1qyvkai":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e2/recall/1"},"4b0fmh":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e3/recall/1"},"o5dcaq":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e3/recall/2"},"llqxkt":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e4/recall/1"},"13z7i6o":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e5/recall/1"},"1vo76hb":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e2/recall/2"},"1mlvl1b":{"a":"relationship","vg":"physio1-hypothalamus-pituitary:e6/relationship/1"},"3irjm0":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e9/recall/1"},"q78u8z":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e8/recall/1"},"1td87mn":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e9/recall/2"},"1wc1afx":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e8/recall/2"},"ue10t0":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e7/recall/1"},"12hx9qu":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e7/recall/2"},"9dgdxz":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e9/recall/3"},"y68w3c":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e1/recall/1"},"1yx78yr":{"a":"recall","vg":"physio1-hypothalamus-pituitary:e9/recall/4"}},"explRev":"cbf58810df74"};
